int value = 2;
switch (value) {
    case 1:
        System.out.print("1");
    case 2:
        System.out.print("2");
    case 3:
        System.out.print("3");
        break;
    default:
        System.out.print("D");
}

outer:
for (int i = 1; i <= 2; i++) {
    for (int j = 1; j <= 2; j++) {
        if (i == 1 && j == 2) {
            continue outer;
        }
        System.out.print(i + "" + j + " ");
    }
}

int code = 500;
String result = switch (code) {
    case 200 -> "Success";
    case 500 -> {
        System.out.print("Error ");
        yield "Failure";
    }
    default -> "Unknown";
};
System.out.print(result);

